{Let $f: \mathcal{P}_2\left(\mathbb{R}\right) \mapsto \mathbb{R}$ be a continuous function, and $I$ be the identity map on $\mathbb{R}^d$.}
\begin{enumerate}[(i)]
	\item {If for any $\mu \in \mathcal{P}_2\left(\mathbb{R}\right)$
$$
T_{\mu, 2} \ni \phi \rightarrow D_\phi^L f(\mu):=\lim _{\varepsilon \rightarrow 0} \frac{f\left(\mu \circ(I+\varepsilon \phi)^{-1}\right)-f(\mu)}{\varepsilon} \in \mathbb{R}
$$
is a well-defined bounded linear functional, then we say that $f$ is intrinsically differentiable at $\mu$ and denote the intrinsic derivative of $f$ at $\mu$ by $D_\phi^L f(\mu)$.}

	\item {If for any $\mu \in \mathcal{P}_2\left(\mathbb{R}\right)$}
$$
\lim _{\|\phi\|_{\mu, 2} \rightarrow 0} \frac{f\left(\mu \circ(I+\varepsilon \phi)^{-1}\right)-f(\mu)-D_\phi^L f(\mu)}{\varepsilon}=0,
$$
we say that $f$ is L-differentiable at $\mu$ and the denote the L-derivative (i.e. Lions derivative) of $f$ at $\mu$ by $D_\mu f(\mu)$.
\end{enumerate}

{
The Assumptions \ref{ass:A_1}-\ref{ass:A_5} will be used as follows:}

	{The Assumption \ref{ass:A_1} which is the standard assumption for MV-SDE and Assumption \ref{ass:A_2} used in \cite{briand2020particles,briand2018bsdes,falkowski2021mean,briandMEAN} ensure the well-posedness of \eqref{eq:1.1}. 
The  Assumption \ref{ass:A_4} will be use in show the Proposition \ref{pro:3.3}.}

{Assumption \ref{ass:A_5} is a dissipative condition which will be used to show the existence and uniqueness of invariant probability measure when $t\rightarrow \infty$. }

\label{thm:1}
	Under Assumptions \ref{ass:A_1} and \ref{ass:A_2}, the MR-MVSDE \eqref{eq:1.1} has a unique deterministic flat solution $(X,K)$. Moreover, 
\begin{equation*}
\forall t \geq 0, \quad K_t=\sup _{s \leq t} \inf \left\{x \geq 0: \mathbb{E}\left[h\left(x+U_s\right)\right] \geq 0\right\}=\sup _{s \leq t} G_0\left(\mathcal{L}_{U_s}\right),
\end{equation*}
where $\left( U_t \right)_{0\leq t\leq T}$ is the process defined by :
\begin{equation}\label{eq:U}
\begin{aligned}
	  U_t = \xi + \int_0^t b(X_s,\mathcal{L}_{X_s})ds + \int_0^t \sigma(X_s,\mathcal{L}_{X_s})dB_s.
\end{aligned}
\end{equation}
With these notations, denoting by $\mathcal{L}_{U_s}$ the family of marginal laws of $\left( U_t \right)_{0\leq t\leq T}$ we have 
$$
K_t = \sup_{s\leq t}G_0(\mathcal{L}_{U_s}).
$$

\label{pro:F-K}
Suppose that Assumptions \ref{ass:A_1} and \ref{ass:A_2} hold. 
	Assume that $u$ is a classical solution to Neumann problem on the Wasserstein space \eqref{eq:FK_f}. Then, $u$ is given by \eqref{eq:FK_u}.

\begin{equation}\label{eq:FK_f}
\left\{\begin{array}{l}
\text { (i) } \left(\partial_t+\mathcal{T}\right) u(t, \mu)=0 \quad \text { in }(0, T) \times \mathcal{O}, \\
\text { (ii) } \int_{\mathbb{R}} {D}_\mu u(t, \mu)(y)  \mu(d y)=0, \quad \text { in }(0, T)\times \partial \mathcal{O}, \\
\text { (iii) } u(T, \mu)=G(\mu), \quad \text { in } \mathcal{O},
\end{array}\right.
\end{equation}
where the operator $\mathcal{T}$ is given, for any smooth function $\phi:[0,T]\times \mathcal{P}_2(\mathbb{R})\rightarrow \mathbb{R}$, by
\begin{equation*}
\begin{aligned}
	  \mathcal{T}\phi(t,\mu) := \int_{\mathbb{R}}b(z,\mu) D_\mu\phi(t,\mu)(z)d\mu(z) + \frac{1}{2}\int_{\mathbb{R}}\sigma(z,\mu)^2\partial_z D_\mu \phi(t,\mu)(z) d\mu(z)\,.
\end{aligned}
\end{equation*}

\label{pro:3.3}
Suppose Assumptions \ref{ass:A_1}, \ref{ass:A_2} and \ref{ass:A_4} hold. Let $(X,K)$ be the unique deterministic flat solution to \eqref{eq:1.1}. Then the process $K$ is Lipschitz continuous and the Stielije measure $dK$ has the following density w.r.t the Lebesgue measure: 
	\begin{equation}\label{eq:density_dk}
k: \mathbb{R}^{+} \ni t \longmapsto \frac{\left(\mathbb{E}\left[\mathcal{A}_{\mathcal{L}_{X_t}} h\left(X_{t}\right)\right]\right)^{-}}{\mathbb{E}\left[h^{\prime}\left(X_{t}\right)\right]} \mathbbm{1}_{\mathbb{E}\left[h\left(X_t\right)\right]=0}\,,
\end{equation}
where, $(\cdot)^{-}:= min(\cdot,0)$.

The proof for the case of MR-SDE is given in \cite{briand2020particles}. We present here the proof of the MR-MVSDE.

\textbf{Step 1: Construct the solution $(X,K)$ of \eqref{eq:1.1}.}

	Let us consider the set 
 $$\mathcal{C}^2 = \left \{ X_t \text{ is } \mathcal{F}_t-\text{adapted continuous process}\,, \mathbb{E}\left( \sup_{0\leq t\leq T}|X_t|^2< \infty \right) \right \} \,.$$
 And let $\widetilde{X}_t\in \mathcal{C}^2$ be a given process. We set 
\begin{equation}
\tilde{U}_t=\xi+\int_0^t b\left(\tilde{X}_s, \mathcal{L}_{\tilde{X}_s}\right) d s+\int_0^t \sigma\left(\tilde{X}_s, \mathcal{L}_{\tilde{X}_s}\right) d B_s, \quad \operatorname{Law}\left(\tilde{U}_s\right)=: \mathcal{L}_{\tilde {U}_s}\,,
\end{equation}
and define the function $K_t$ by setting
$$
{K_t=\sup _{s \leq t} \inf \left\{x \geq 0: \mathbb{E}\left[h\left(x+\tilde{U}_s\right)\right] \geq 0\right\}=G_0\left(\mathcal{L}_{\tilde {U}_s}\right)}\,.
$$
The function $K_t$ being given, let us define the process $X_t$ by the formula
\begin{equation}
\begin{aligned}
	  X_t=\xi+\int_0^t b\left(\tilde{X}_s,\mathcal{L}_{\tilde{X}_s}\right) d s+\int_0^t \sigma\left(\tilde{X}_s,\mathcal{L}_{\tilde{X}_s}\right) d B_s+K_t .
\end{aligned}
\end{equation}


\textbf{Step 2: Check $K_t$ satisfies $\mathbb{E}\left[h\left(X_t\right)\right] \geq 0$ and $\int_0^t \mathbb{E}\left[h\left(X_s\right)\right] d K_s=0$.}


Based on the definition of $K_t$, we have $\mathbb{E}\left[ h(X_t) \right]\geq 0$, $K_t = G_0\left( \mathcal{L}_{\tilde{U}_t} \right), dK_t-a.e.$ and $G_0(\mathcal{L}_{\tilde{U}_t})>0, dK_t-a.e.$ Then we obtain 
$$
\begin{aligned}
\int_0^t \mathbb{E}\left[h\left(X_s\right)\right] d K_s & =\int_0^t \mathbb{E}\left[h\left(\tilde{U}_s+K_s\right)\right] d K_s \\
& =\int_0^t \mathbb{E}\left[h\left(\tilde{U}_s+G_0\left(\mathcal{L}_{\tilde{U}_s}\right)\right)\right] d K_s \\
& =\int_0^t \mathbb{E}\left[h\left(\tilde{U}_s+G_0\left(\mathcal{L}_{\tilde{U}_s}\right)\right)\right] \mathbbm{1}_{\left \{ G_0\left(\mathcal{L}_{\tilde{U}_s}\right)>0 \right \}} d K_s .
\end{aligned}
$$
Moreover, since $h$ is continuous, we have $\mathbb{E}\left[h\left(\tilde{U}_s+G_0\left(\mathcal{L}_{\tilde{U}_s}\right)\right)\right]=0$ as soon as $G_0\left(\mathcal{L}_{\tilde{U}_s}\right)>0$, so that
$$
\int_0^t \mathbb{E}\left[h\left(X_s\right)\right] d K_s=0\,.
$$

\textbf{Step 3: Show the solution map $\Phi$ which associates to $\tilde{X}$ to the solution $X$ of \eqref{eq:1.1} is a contraction.}

 Let $\tilde{X}, \tilde{X}^\prime \in \mathcal{C}^2$ and define $\tilde{U}$, $K$ and $\tilde{U}^\prime$, $K^\prime$ as above, using the some Brownian motion. We have from the Lipschitz assumption of $b$ and $\sigma$, Cauchy-Schwarz inequality and Burkholder-Davis-Gundy (B-D-G) inequality 
 \begin{equation}\label{eq:Th_1.1}
\begin{aligned}
	  &\mathbb{E}\left[ \sup_{t\leq T}|\tilde{X}_t - \tilde{X}_t^\prime|^2 \right]\\
	  &\leq  3\mathbb{E} \left[\sup_{t\leq T}\left\{\left|\int_0^t\left( b\left( \tilde{X}_s,\mathcal{L}_{\tilde{X}_s} \right)- b\left( \tilde{X}^\prime_s,\mathcal{L}_{\tilde{X}^\prime_s} \right) 
	   \right)ds\right|^2 + \left|\int_0^t \left( \sigma\left( \tilde{X}_s,\mathcal{L}_{\tilde{X}_s} \right)-\sigma\left( \tilde{X}^\prime_s,\mathcal{L}_{\tilde{X}^\prime_s} \right) \right)dB_s\right|^2\right.\right.\\
	  &\left.\left.\qquad +\left|K_t - K^\prime_t\right|^2 \right\}\right]\\
	  &\leq3 \mathbb{E}\left[\left.T\cdot \sup _{t \leq T} \int_0^t\left(b\left(\tilde{X}_s, \mathcal{L}_{\tilde{X}_s}\right)-b\left(\tilde{X}_s^{\prime}, \mathcal{L}_{\tilde{X}_s^{\prime}}\right)\right) d s\right|^2\right]
   \\
	  &\qquad
   +3 \mathbb{E}\left[\sup _{t \leq T}\left|\int_0^t\left(\sigma\left(\tilde{X}_s, \mathcal{L}_{\tilde{X}_s}\right)-\sigma\left(\tilde{X}^{\prime}_s, \mathcal{L}_{\tilde{X}^{\prime}_s}\right)\right) d B_s\right|^2\right] + 3 \sup_{t\leq T}\left|K_t - K^\prime_t\right|^2 \\
	  & \leq CT\left \{ T\mathbb{E}\left[ \sup_{t\leq T}\left|\tilde{X}_t - \tilde{X}^\prime_t\right| \right]+\mathbb{E}\left[ \int_0^T \mathcal{W}_2\left( \mathcal{L}_{\tilde{X}_s},\mathcal{L}_{\tilde{X}^\prime_s} \right)^2ds  \right] \right \}\\
	  &\qquad+ CT \mathbb{E}\left[ \sup_{t\leq T}\left|\tilde{X}_t - \tilde{X}^\prime_t\right| \right]+CT\mathbb{E}\left[ \int_0^T \mathcal{W}_2\left( \mathcal{L}_{\tilde{X}_s},\mathcal{L}_{\tilde{X}^\prime_s} \right)^2ds  \right]+ 3 \sup_{t\leq T}\left|K_t - K^\prime_t\right|^2   \,.
\end{aligned}
\end{equation}
From the representation of $K$ and Lemma \ref{lem:2.2}, we have 
\begin{equation}\label{eq:K_t}
\begin{aligned}
	  \sup_{t\leq T}|K_t-K^\prime_t|^2 &= \sup_{t\leq T}\left|\sup_{s\leq t}G_0(\mathcal{L}_{\tilde X_t})-\sup_{s\leq t}G_0(\mathcal{L}_{\tilde X_t^\prime})\right|\leq \sup_{t\leq T}\left|G_0(\mathcal{L}_{\tilde X_t})-G_0(\mathcal{L}_{\tilde X_t^\prime})\right|\\
	  &\leq \frac{M}{m} \mathbb{E}\left[\sup _{t \leq T}\left|\tilde{U}_t-\tilde{U}^{\prime}_t\right|^2\right] \leq  C\mathbb{E}\left[\sup _{t \leq T}\left|\tilde{X}_t-\tilde{X}_t^{\prime}\right|^2\right] \,.
\end{aligned}
\end{equation}
Plugging \eqref{eq:K_t} into \eqref{eq:Th_1.1}, we have 
$$
\mathbb{E}\left[ \sup_{t\leq T}|\tilde X_t - \tilde X_t^\prime| \right]\leq  C(1+T) T \mathbb{E}\left[\sup _{t \leq T}\left|\tilde{X}_t-\tilde{X}_t^{\prime}\right|^2\right].
$$

























Hence, there exists a positive $\tilde{T}$, depending on $b, \sigma$ and $h$ only, such that for all $T<\tilde{T}$, the map $\Phi$ is a contraction. We first deduce the existence and uniqueness of the solution on $[0, \tilde{T}]$ and then on $\mathbb{R}^{+}$ by iterating the construction.

(i) We have 
	\begin{equation}\label{eq:pro_3_2_1}
\begin{aligned}
\mathbb{E}\left[\sup _{t \leq T}\left|X_t\right|^p\right] & \leq 4^{p-1}\left\{\mathbb{E}\left[|\xi|^p\right]+\mathbb{E}\left[\sup _{t \leq T}\left(\int_0^t\left|b\left(X_s, \mathcal{L}_{X_s}\right)\right| d s\right)^p\right]\right. \\
& \left.+\mathbb{E}\left[\sup _{t \leq T}\left(\int_0^t\left|\sigma\left(X_s, \mathcal{L}_{X_s}\right)\right| d B_s\right)^p\right]+K_T^p\right\}\,.
\end{aligned}
\end{equation}
We first deal with $K^p_T = \sup_{t\leq T}G_0(\mathcal{L}_{U_t})$. Apply Lipschitz property of $G_0$, Lemma \ref{lem:2.2} and the definition of the Wasserstein metric $\mathcal{W}_1$, we have 
$$
\forall t \geq 0, \quad \left|G_0(\mathcal{L}_{U_t})\right|\leq \frac{M}{m}\mathbb{E}\left[ |U_t - U_0| \right],
$$
since $G_0(\mathcal{L}_{U_0}) = 0$ as $\mathbb{E}\left[ h(X_0) \right]\geq 0$, and where $U$ is defined by \eqref{eq:U}. Therefore 
\begin{equation}\label{eq:pro_3_2_2}
\begin{aligned}
	  |K_T|^p = \left|\sup_{t\leq T}G_0(\mathcal{L}_{U_t})\right|^p & \leq  2^{p-1}\left\{ \left( \frac{M}{m} \right)^p\mathbb{E}\left[ \sup_{t\leq T}\left( \int_0^t\left|b(X_s,\mathcal{L}_{X_s})\right|ds \right)^p \right]\right . \\
	  &\qquad \left .+ \mathbb{E}\left[ \sup_{t\leq T}\left( \int_0^t\left|\sigma(X_s,\mathcal{L}_{X_s})\right|dB_s \right)^p \right]\right\}\,.
\end{aligned}
\end{equation}
Plugging \eqref{eq:pro_3_2_2} into \eqref{eq:pro_3_2_1}, we deduce that there exists a constant $C_p\geq 0$ such that 
\begin{equation}
\begin{aligned}
	  \mathbb{E}\left[ \sup_{t\leq T}|X_t|^p \right]&\leq C_p \mathbb{E}\left[ |\xi|^p + \sup_{t\leq T}\left( \int_0^t\left|b(X_s,\mathcal{L}_{X_s})\right|ds \right)^p + \sup_{t\leq T}\left|\int_0^t \sigma\left( X_s,\mathcal{L}_{X_s} \right)dB_s\right|^p \right]\\
	  &\leq C_p\left \{ \mathbb{E}\left[ |\xi|^p \right] + T^{p-1}\mathbb{E}\left[ \int_0^T(1+|X_s|)^pds \right] + C\mathbb{E}\left[ \int_0^T(1+|X_s|)^2ds \right]^{\frac{p}{2}} \right \}\\
	  &\leq C_p(1+\mathbb{E}\left[ |\xi|^p \right]) + C \int_0^T\mathbb{E}\left[ \sup_{t\leq r}|X_t|^p \right]dr\,.
\end{aligned}
\end{equation}
Apply Gronwall's lemma, we deduce for all $p\geq 2$, there exists a constant $C>0$ such that 
$$
\mathbb{E}\left[ \sup_{t\leq T}|X_t|^p \right] \leq C(1+\mathbb{E}\left[ |\xi|^p \right]).
$$

(ii) we observe that $\nu \rightarrow G_0(\nu)$ is Lipschitz continuous, we have 
$$
K_t - K_s = \sup_{r\leq t}G_0(\mathcal{L}_{U_r}) -\sup_{r\leq s}G_0(\mathcal{L}_{U_r})\leq \frac{M}{m}\mathcal{W}_1(\mathcal{L}_{U_r},\mathcal{L}_{U_s})\leq \frac{M}{m}\mathbb{E}\left[ \left|U_r - U_s\right| \right],
$$
so the result follows from standard computations.

(iii) we use the decomposition 
$$X_t - X_s = U_t - U_s + K_t - K_s\,,
$$
As a result of (ii), we complete this proof.

Firstly, we show $K$ is Lipschitz continuous. To do so, we prove that $s\mapsto \bar{G}_0(\mu_s) $ is Lipschitz continuous on $[0,T]$. If $s \leq t$, we have 
$$

\begin{aligned}
\left|\bar{G}_0\left(\mathcal{L}_{U_s}\right)-\bar{G}_0\left(\mathcal{L}_{U_t}\right)\right| & \leq \frac{1}{m}\left|H\left(\bar{G}_0\left(\mathcal{L}_{U_s}\right), \mathcal{L}_{U_t}\right)\right| \\
& =\frac{1}{m}\left|\mathbb{E}\left[h\left(\bar{G}_0\left(\mathcal{L}_{U_s}\right)+U_t\right)\right]\right| \\
& =\frac{1}{m}\left|\mathbb{E}\left[h\left(\bar{G}_0\left(\mathcal{L}_{U_s}\right)+U_s+\int_s^t b\left(X_r,\mathcal{L}_{X_r}\right) d r+\int_s^t \sigma\left(X_r,\mathcal{L}_{X_r}\right) d B_r\right)\right]\right| ,
\end{aligned}
$$
the first equality since $H(\bar{G}_0(\mu_t),\mu_t) = 0$.

Let $\bar{A}_{x,\mu}$ be the partial operator of second order defined by 
$$
\bar{\mathcal{A}}_{y,\mu}f(x) := b(y,\mu) \frac{\partial }{\partial x}f(x) + \frac{1}{2}\sigma\left( y,\mu \right)^2\frac{\partial^2}{\partial x^2}f(x)\,.
$$
Apply It\^{o}'s lemma, we have 
\begin{equation}
\begin{aligned}
	  \mathbb{E}\left[ h\left( \bar{G}_0(\mathcal{L}_{U_s}) + U_t \right) \right] &= \mathbb{E}\left[ h\left( \bar{G}_0(\mathcal{L}_{U_s})+U_s \right) \right] + \int_s^t\mathbb{E}\left[ \bar{\mathcal{A}}_{X_r,\mathcal{L}_{X_r}}h\left( \bar{G}_0(\mathcal{L}_{U_s}) + U_r \right) \right]dr \\
	  &=H\left(\bar{G}_0\left(\mathcal{L}_{U_s}\right), \mathcal{L}_{U_s}\right)+\int_s^t\mathbb{E}\left[ \bar{\mathcal{A}}_{X_r,\mathcal{L}_{X_r}}h\left( \bar{G}_0(\mathcal{L}_{U_s}) + U_r \right) \right]dr\\
	  & = \int_s^t\mathbb{E}\left[ \bar{\mathcal{A}}_{X_r,\mathcal{L}_{X_r}}h\left( \bar{G}_0(\mathcal{L}_{U_s}) + U_r \right) \right]dr.
\end{aligned}
\end{equation}
The result follows that $h$ has bounded derivatives and $\sup_{t\leq T}|X_t|\in L^2$ for each $T>0$. So from \cite{briand2020particles}, we deduce that $K$ is Lipschitz continuous and has a bounded density on $[0,T]$ for each $T>0$. 

Then we show the density of $dK$ is \eqref{eq:density_dk}. From Assumption \ref{ass:A_4} and apply It\^{o}'s lemma, for any $s\leq t$ we can get
\begin{equation*}
\begin{aligned}
	  h(X_t) - h(X_s) &= \int_s^tb(X_r,\mathcal{L}_{X_r})h^{\prime}(X_r)dr + \int_s^t \sigma (X_r,\mathcal{L}_{X_r})h^{\prime}(X_r)dB_r \\
	  &\qquad+ \frac{1}{2}\int_s^t \sigma (X_r,\mathcal{L}_{X_r})^2h^{\prime}(X_r)d r  + \int_s^t h^{\prime}(X_r)dK_r \\
	  & =\int_s^t \mathcal{A}_{\mathcal{L}_{X_r}}h(X_r)dr + \int_s^t h^\prime(X_r)dK_r + \int_s^t \sigma\left( X_r,\mathcal{L}_{X_r} \right)dB_r \,.
\end{aligned}
\end{equation*}
Then, we obtain 
\begin{equation}\label{eq:pro_3.4_1}
\begin{aligned}
	  \mathbb{E}\left[ \int_s^t h^\prime(X_r)dK_r \right] = \mathbb{E} h(X_t) - \mathbb{E} h(X_s) - \int_s^t \mathbb{E} \mathcal{A}_{\mathcal{L}_{X_r}}h(X_r)dr\,.
\end{aligned}
\end{equation}

Using \eqref{eq:pro_3.4_1}, Lemma \ref{lem:3.3} , and the proof of \cite{briand2020particles}[Proposition 2.7], we can get the density of $dK$ w.r.t the Lebesgue measure is 
$$
k_t = \frac{\left(\mathbb{E}\left[\mathcal{A}_{\mathcal{L}_{X_t}} h\left(X_{t}\right)\right]\right)^{-}}{\mathbb{E}\left[h^{\prime}\left(X_{t}\right)\right]} \mathbbm{1}_{\mathbb{E}\left[h\left(X_t\right)\right]=0}\,.
$$
Then, we complete the proof.

Similar \cite{briand2020particles} and \cite{briandMEAN}, the previous system of interacting particles can be seen as a multidimensional reflected SDE with oblique reflection. If $h$ is concave, the set
$$
\mathcal{S} := \left \{ \left( x_1,\cdots,x_n \right)\in \mathbb{R}^n: h(x_1) + \cdots + h(x_n) \geq 0 \right \}
$$
 is convex and the system 
 \begin{equation*}
\left\{\begin{array}{l}
  X^{i}_t = \hat{\xi} + \int_0^t b\left(X^i_s, \frac{1}{n}\sum_{j = 1}^n \delta_{x^j_s}\right) d s+\int_0^t \sigma\left(X^i_s,\frac{1}{n}\sum_{j = 1}^n \delta_{x^j_s}\right) d B^i_s + K^n_t, \quad 1\leq i\leq n\\
\frac{1}{n}\sum_{i = 1}^n h(X^i_t)\geq 0,\quad \frac{1}{n}\sum_{i = 1}^n\int_0^th(X^i_t)dK^n_s = 0
\end{array}\right.
\end{equation*}
is the SDE with oblique reflection in convex $\mathcal{S}$.

Let $t >0$, for $r \leq t$, we have 
\begin{equation}
\begin{aligned}
\left|X_r^j-\bar{X}_r^j\right| \leq & \left|\hat{\xi}^j-\xi^j\right| \\
& +\int_0^r\left|b\left(X_s^j, \frac{1}{n}\sum_{j = 1}^n \delta_{x^j_s}\right)-b\left(\bar{X}_s^j,\mathcal{L}_{\bar{X}^j_s}\right)\right| d s\\
&+\left|\int_0^r\left(\sigma\left(X_s^j,\frac{1}{n}\sum_{j = 1}^n \delta_{x^j_s}\right)-\sigma\left(\bar{X}_s^j,\mathcal{L}_{\bar{X}_s}\right)\right) d B_s^j\right| \\
& +\left|\sup _{s \leq r} G_0\left(\mathcal{L}_{U^{\xi}_s}\right)-\sup _{s \leq r} G_0\left(\mathcal{L}_{\bar{U}^i_s}\right)\right| .
\end{aligned}
\end{equation}

From the inequality 
$$
\begin{aligned}
\left|\sup _{s \leq r} G_0\left(\mathcal{L}_{U^{\xi}_s}\right)-\sup _{s \leq r} G_0\left(\mathcal{L}_{\bar{U}^i_s}\right)\right| & \leq \sup _{s \leq r}\left|G_0\left(\mathcal{L}_{U^{\xi}_s}\right)-G_0\left(\mathcal{L}_{\bar{U}^i_s}\right)\right| \leq \sup _{s \leq t}\left|G_0\left(\mathcal{L}_{U^{\xi}_s}\right)-G_0\left(\mathcal{L}_{\bar{U}^i_s}\right)\right| \\
& \leq \sup _{s \leq t}\left|G_0\left(\mathcal{L}_{U^{\xi}_s}\right)-G_0\left(\mathcal{L}_{\tilde{U}_s}\right)\right|+\sup _{s \leq t}\left|G_0\left(\mathcal{L}_{\tilde{U}_s} \right)-G_0\left(\mathcal{L}_{\bar{U}^i_s}\right)\right|,
\end{aligned}
$$
where $\mathcal{L}_{\tilde{U}_s}:=\frac{1}{n}\sum_{i=1}^n\delta_{\bar{U}^i_s}$.
We have 
\begin{equation*}
\begin{aligned}
	  \sup_{r\leq t}\left|X^j_r - \bar{X}^j_r\right|\leq I^j_1(r) +  \sup _{s \leq t}\left|G_0\left(\mathcal{L}_{U^N_s}\right)-G_0\left(\mathcal{L}_{\tilde{U}_s}\right)\right|+\sup _{s \leq t}\left|G_0\left(\mathcal{L}_{\tilde{U}_s}\right)-G_0\left(\mathcal{L}_{\bar{U}^j_s}\right)\right|,
\end{aligned}
\end{equation*}
where, $I^j_1$ is defined by 
\begin{equation*}
\begin{aligned}
	  I^j_1 = \int_0^t \left|b\left( X^j_s, \frac{1}{n}\sum_{j=1}^n \delta_{X^j_s} \right)-b\left( \bar{X}^j_s,\mathcal{L}_{\bar{X}^j_s} \right)\right|ds + \left|\int_0^t \sigma\left( X^j_s, \frac{1}{n}\sum_{i=1}^n \delta_{X^j_s} \right)-\sigma\left( \bar{X}^j_s,\mathcal{L}_{\bar{X}^j_s} \right)\right|dB^j_s\,.
\end{aligned}
\end{equation*}
We have 
\begin{equation*}
\begin{aligned}
	  \mathbb{E}\left[ |I^j_1(t)|^2 \right] &\leq C\mathbb{E}\left[ t\int_0^t\left|b\left( X^j_s, \frac{1}{n}\sum_{j=1}^n \delta_{X^j_s} \right)-b\left( \bar{X}^j_s,\mathcal{L}_{\bar{X}^j_s} \right)\right|^2ds \right]\\
	  &\qquad +C\mathbb{E}\left[ \int_0^t\left| \sigma\left( X^j_s, \frac{1}{n}\sum_{j=1}^n \delta_{X^j_s} \right)-\sigma\left( \bar{X}^j_s,\mathcal{L}_{\bar{X}^j_s} \right)\right|^2ds \right]\\
	  &\leq C t \int_0^t\mathbb{E}\left[ \left|X^j_s - \bar{X}^j_s\right|^2 + \mathcal{W}_2\left( \frac{1}{n}\sum_{j=1}^n\delta_{X^j_s},\mathcal{L}_{\bar{X}^j_s} \right)^2 \right]ds \\
	  &\qquad + C \int_0^t\mathbb{E}\left[ \left|X^j_s - \bar{X}^j_s\right|^2 + \mathcal{W}_2\left( \frac{1}{n}\sum_{j=1}^n\delta_{X^j_s},\mathcal{L}_{\bar{X}^j_s} \right)^2 \right]ds\\
	  & = C(1+t)\int_0^t\mathbb{E}\left[ \left|X^j_s-\bar{X}^j_s\right|^2 \right]ds + C(1+t)\int_0^t\mathbb{E}\left[ \mathcal{W}_2\left( \frac{1}{n}\sum_{j=1}^n\delta_{X^j_s},\mathcal{L}_{\bar{X}^j_s} \right)^2 \right]ds\,.
\end{aligned}
\end{equation*}

We have 
$$
\sup _{s \leq t}\left|G_0\left(\mathcal{L}_{U^{\xi}_s}\right)-G_0\left(\mathcal{L}_{\tilde{U}_s}\right)\right| \leq \frac{M}{m} \sup _{s \leq t} \frac{1}{n} \sum_{j=1}^n\left|U_s^j-\bar{U}_s^j\right| \leq \frac{M}{m} \frac{1}{n} \sum_{j=1}^n \sup _{s \leq t}\left|U_s^j-\bar{U}_s^j\right|\,.
$$

Moreover, taking into account that the variables are exchangeable, the Cauchy-Schwarz inequality implies
$$
\mathbb{E}\left[\sup _{s \leq t}\left|G_0\left(\mathcal{L}_{U^{\xi}_s}\right)-G_0\left(\mathcal{L}_{\tilde{U}_s}\right)\right|^2\right] \leq \frac{M^2}{m^2} \frac{1}{n} \sum_{j=1}^n \mathbb{E}\left[\sup _{s \leq t}\left|U_s^j-\bar{U}_s^j\right|^2\right]=\frac{M^2}{m^2} \mathbb{E}\left[\sup _{s \leq t}\left|U_s^j-\bar{U}_s^j\right|^2\right]\,.
$$
Since
\begin{equation*}
\begin{aligned}
	  U^j_s - \bar{U}^j_s = \int_0^s b\left( X^j_r,\frac{1}{n}\sum_{j = 1}^n\delta_{X^j_r} \right) - b\left( \bar{X}^j_r,\mathcal{L}_{\bar{X}^j_r} \right)ds + \int_0^s \sigma\left( X^j_r,\frac{1}{n}\sum_{i = 1}^n\delta_{X^j_r} \right) - \sigma\left( \bar{X}^j_s,\mathcal{L}_{\bar{X}^j_s} \right)dB^j_s\,,
\end{aligned}
\end{equation*}
we have 
$$
\mathbb{E}\left[ \sup_{s\leq t} 
\left|G_0(\mathcal{L}_{U^{\xi}_s}) - G_0(\mathcal{L}_{\bar{U}^j_s})\right| \right] 
\leq C\frac{M^2}{m^2}(1+t) \left \{ \int_0^t\mathbb{E}\left[ \left|X^j_s - \bar{X}^j_s\right|^2 \right] + \mathbb{E}\left[ \mathcal{W}_2\left( \frac{1}{n}\sum_{j=1}^n\delta_{X^j_s},\mathcal{L}_{\bar{X}^j_s} \right)^2 \right]ds \right \}\,.
$$
Next, dealing with the $\mathbb{E}\left[ \mathcal{W}_2\left( \frac{1}{n}\sum_{i=1}^N\delta_{X^i_s},\mathcal{L}_{\bar{X}^j_s} \right)^2 \right]$terms. 
By the triangle inequality, we get
\begin{equation*}
\begin{aligned}
\mathbb{E}\left[ \mathcal{W}_2\left( \frac{1}{n}\sum_{i=1}^n\delta_{X^i_s},\mathcal{L}_{\bar{X}^j_s} \right) \right]\leq \mathbb{E}\left[ \left( \frac{1}{n}\sum_{j = 1}^n\left|X^j_s - \bar{X}^j_s\right|^2 \right)^{\frac{1}{2}}+\mathcal{W}_2\left( \frac{1}{n}\sum_{j = 1}^n\delta_{\bar{X}^j_s},\mathcal{L}_{\bar{X}^j_s} \right) \right]\,.
\end{aligned}
\end{equation*}
Noting that the particles are exchangeable and from \cite{PTMFG}, we have 
$$
\mathbb{E}\left[ \mathcal{W}_2\left( \frac{1}{n}\sum_{j=1}^n\delta_{X^j_s},\mathcal{L}_{\bar{X}^j_s} \right)^2 \right] \leq C \mathbb{E}\left[ \left|X^j_s - \bar{X}^j_s\right| \right]   + C n^{-\frac{1}{2}}\,.
$$
Consequently, we have 
\begin{equation}
\begin{aligned}
	  \mathbb{E}\left[ \sup_{r\leq t}\left|X^j_r - \bar{X}^j_r\right|^2 \right]& \leq  2 A \int_0^t\mathbb{E}\left[ \sup_{r\leq s}\left|X^j_r - \bar{X}^j_r\right|^2 \right]ds\\
   &\qquad+ 4 \mathbb{E}\left[ \sup_{s\leq t}\left|G_0(\mathcal{L}_{{U}^{\xi}_s}) - G_0\left( \mathcal{L}_{\tilde{U}_s} \right)\right|^2 \right] + A T n^{-\frac{1}{2}},
\end{aligned}
\end{equation}
where $A = C(1+t) (1 + M^2/m^2)$. 
Apply Gronwall's lemma, we deduce that 
\begin{equation*}
\begin{aligned}
	  \mathbb{E}\left[ \sup_{r\leq t}\left|X^j_r - \bar{X}^j_r\right|^2 \right]\leq 2Ce^{A}
	  \left \{ \mathbb{E}\left[ \sup_{s\leq t}\left|G_0(\mathcal{L}_{{U}^{\xi}_s}) - G_0\left( \mathcal{L}_{\tilde{U}_s} \right)\right|^2 \right] 
	  + AT n^{-\frac{1}{2}} \right \}\,.
\end{aligned}
\end{equation*}
In view of Lemma \ref{lem:2.2}, we have
$$
\mathbb{E}\left[\sup _{s \leq t}\left|G_0\left(\mathcal{L}_{{U}^{\xi}_s}\right)-G_0\left(\mathcal{L}_{\tilde{U}_s}\right)\right|^2\right] \leq \frac{1}{m^2} \mathbb{E}\left[\sup _{s \leq t}\left|\int h\left(\bar{G}_0\left(\mathcal{L}_{U^{\xi}_s}\right)+\cdot\right)\left(d \mathcal{L}_{{U}^\xi_s}-d \mathcal{L}_{\tilde{U}_s}\right)\right|^2\right]\,,
$$
which leads to
$$
\mathbb{E}\left[\sup _{r \leq t}\left|X_r^j-\bar{X}_r^j\right|^2\right] \leq C e^{A}\left \{  \frac{1}{m^2} \mathbb{E}\left[\sup _{s \leq t}\left|\int h\left(\bar{G}_0\left(\mathcal{L}_{U^{\xi}_s}\right)+\cdot\right)\left(d \mathcal{L}_{{U}^\xi_s}-d \mathcal{L}_{\tilde{U}_s}\right)\right|^2\right] +ATn^{-\frac{1}{2}} \right \}\,.
$$

As $h$ is Lipschitz continuous, the convergence rate is determined by the empirical measure convergence of independent and identically distributed diffusion processes. However, obtaining the standard convergence rate is not straightforward since we require uniform convergence in time. If we only suppose that Assumptions \ref{ass:A_1} and \ref{ass:A_2} holds, we obtain that
$$
\frac{1}{m^2} \mathbb{E}\left[\sup _{s \leq t}\left|\int h\left(\bar{G}_0\left(\mathcal{L}_{\tilde{U}_s}\right)+\cdot\right)\left(d \mathcal{L}_{{U}^{\xi}_s}-d \mathcal{L}_{\tilde{U}_s}\right)\right|^2\right]\leq \frac{M^2}{m^2} \mathbb{E}\left[\sup _{s \leq t} \mathcal{W}_1\left(\mathcal{L}_{{U}^{\xi}_s}, \mathcal{L}_{\tilde{U}_s}\right)^2\right]\,.
$$


In view of the proof of \cite{briand2020particles}[Theorem 3.3 Part (i)]
, we have 
$$
\mathbb{E}\left[ \sup_{s\leq t}\mathcal{W}_1\left( \mathcal{L}_{\bar{U}^N_s}, \mathcal{L}_{U_s} \right)^2 \right]\leq Cn^{-\frac{1}{2}}\,.
$$
So, we have there exists a constant $C>0$
\begin{equation*}
\begin{aligned}
	  \mathbb{E}\left[ \sup_{r\leq t}\left|X^j_r - \bar{X}^j_r\right|^2 \right]\leq Ce^A\left( C \frac{M^2}{m^2}+ AT \right)n^{-\frac{1}{2}}\leq C n^{-\frac{1}{2}}\,.
\end{aligned}
\end{equation*}
Then, we complete this proof.

Let $\{\xi_i\}_{i=1}^n$ be a sequence in $\mathbb{R}$ and $\lim_{i\rightarrow \infty} \xi_i = \xi$. We will show that 
	$$
	\lim_{n\rightarrow \infty} \mathbb{E}\left[ \sup_{t\leq T}\left|X^{\xi_n}_t - X^\xi_t\right|^2 \right] = 0.
	$$
	That means the mapping $\Xi$ is continuous.

	Apply the Lipschitz condition of $b$ and $\sigma$, and Cauchy-Schwarz inequality, we have 
	\begin{equation*}
\begin{aligned}
	  \mathbb{E}\left[ \sup_{t\leq T}\left|X^{\xi_n}_t - X^{\xi}_t\right|^2 \right] &\leq 4\left|\xi_n - \xi\right|^2 + 4\mathbb{E}\left[ \sup_{t\leq T}\int_0^t\left|b\left( X_s^{\xi_n},\mathcal{L}_{X_s^{\xi_n}} \right)-b\left( X_s^{\xi},\mathcal{L}_{X_s^{\xi}} \right)\right|ds \right]^2\\
	  &\qquad +4\mathbb{E}\left[ \sup_{t\leq T} \int_0^t \left|\sigma\left( X_s^{\xi_n},\mathcal{L}_{X_s^{\xi_n}} \right)-\sigma\left( X_s^{\xi},\mathcal{L}_{X_s^{\xi}} \right)\right|dB_s \right]^2 \\&\qquad  + 4 \sup_{t\leq T}\left|K^{\xi_n}_t - K^\xi_t\right|^2\\
	  &\leq 4\left|\xi_n - \xi\right|^2 + 4 T\mathbb{E}\left[ \int_0^t \left|b\left( X_s^{\xi_n},\mathcal{L}_{X_s^{\xi_n}} \right)-b\left( X_s^{\xi},\mathcal{L}_{X_s^{\xi}} \right)\right|^2ds \right]\\
	  &\qquad +4C\mathbb{E}\left[ \int_0^t \left|\sigma\left( X_s^{\xi_n},\mathcal{L}_{X_s^{\xi_n}} \right)-\sigma\left( X_s^{\xi},\mathcal{L}_{X_s^{\xi}} \right)\right|^2ds \right]  
   \\
   &\qquad + 4 \sup_{t\leq T}\left|K^{\xi_n}_t - K^\xi_t\right|^2\\
	  &\leq 4|\xi_n - \xi| + 4TC \mathbb{E}\left[ \int_0^t \left|X^{\xi_n}_s - X^\xi_s\right|^2 + \mathcal{W}_2\left( \mathcal{L}_{X^{\xi_n}_s},\mathcal{L}_{X^\xi_s} \right)^2ds \right] \\
	  &\qquad+ 4C\mathbb{E}\left[ \int_0^t \left|X^{\xi_n}_s - X^\xi_s\right|^2 + \mathcal{W}_2\left( \mathcal{L}_{X^{\xi_n}_s},\mathcal{L}_{X^\xi_s} \right)^2ds \right]  \\
   &\qquad + 4 \sup_{t\leq T}\left|K^{\xi_n}_t - K^\xi_t\right|^2\,,
	  \end{aligned}
\end{equation*}
and 
\begin{equation*}
\begin{aligned}
	  	\sup_{t\leq T}\left|K^{\xi_n}_t - K^\xi_t\right|^2&\leq \frac{M^2}{m^2}\mathbb{E}\left[ \sup_{r\in [0,t]}\left|U^{\xi_n}_r - U_r^\xi\right|^2 \right] \\
	  	&\leq \frac{M^2}{m^2}\left \{ 4|\xi_n - \xi| + (4T+1)C \mathbb{E}\left[ \int_0^t \left|X^{\xi_n}_s - X^\xi_s\right|^2 + \mathcal{W}_2\left( \mathcal{L}_{X^{\xi_n}_s},\mathcal{L}_{X^\xi_s} \right)^2ds \right]  \right \}
\end{aligned}
\end{equation*}
Apply Gronwall's lemma, we have 
\begin{equation}
\begin{aligned}
	\mathbb{E}\left[ \sup_{t\leq T}\left|X^{\xi_n}_t - X^{\xi}_t\right|^2 \right] \leq 4\exp\left \{ C(1+\frac{M^2}{m^2}) \right \}
	\end{aligned}|\xi_n - \xi|^2\,.
\end{equation}
Letting $n$ goes to infinity, we complete this proof.

Apply the Lipschitz condition of $b^n$ and $\sigma^n$, and Cauchy-Schwarz inequality ,we have 
	\begin{equation*}
\begin{aligned}
	  \mathbb{E}\left[ \sup_{t\leq T}\left|X^n_t - X_t\right|^2 \right]&\leq 4\mathbb{E}\left[ \int_0^t b^n\left( X^n_s,\mathcal{L}_{X^n_s} \right)-b^n\left( X_s,\mathcal{L}_{X_s} \right)ds \right]^2\\
	  &\qquad +4\mathbb{E}\left[ \int_0^t b^n\left( X_s,\mathcal{L}_{X_s} \right)-b\left( X_s,\mathcal{L}_{X_s} \right)ds \right]^2\\
	  &\qquad +4\mathbb{E}\left \{ \sup_{t\leq T}\left[ \int_0^t \sigma^n\left( X^n_s,\mathcal{L}_{X^n_s} \right)-\sigma^n\left( X_s,\mathcal{L}_{X_s} \right)dB_s \right]^2 \right \}\\
	  &\qquad +4\mathbb{E}\left \{ \sup_{t\leq T}\left[ \int_0^t \sigma^n\left( X_s,\mathcal{L}_{X_s} \right)-\sigma\left( X_s,\mathcal{L}_{X_s} \right)dB_s \right]^2 \right \} +4\sup_{t\leq T}\left|K^n_t - K_t\right|^2\\
	  &\leq 4(CT+C)\int_0^t\mathbb{E}\left[ |X^n_s-X_s|^2 \right] + \mathcal{W}_2\left( \mathcal{L}_{X^n_s},\mathcal{L}_{X_s} \right)^2ds +C \lambda_n \\
   &\qquad+4\sup_{t\leq T}\left|K^n_t - K_t\right|^2,
\end{aligned}
\end{equation*}
where 
$$
\lambda_n = \mathbb{E}\left[ \int_0^t \left|b^n(X_s,\mathcal{L}_{X_s}) - b(X_s,\mathcal{L}_{X_s})\right|^2  + \left|\sigma^n(X_s,\mathcal{L}_{X_s}) - \sigma(X_s,\mathcal{L}_{X_s})\right|^2ds \right].
$$
Then, we control  $\sup_{t\leq T}\left|K^{n}_t - K_t\right|^2$:
\begin{equation*}
\begin{aligned}
	  	\sup_{t\leq T}\left|K^{n}_t - K_t\right|^2&\leq \frac{M^2}{m^2}\mathbb{E}\left[ \sup_{r\in [0,t]}\left|U^{n}_r - U_r\right|^2 \right] \\
	  	&\leq \frac{M^2}{m^2}4(CT+C)\int_0^t\mathbb{E}\left[ |X^n_s-X_s|^2 \right] + \mathcal{W}_2\left( \mathcal{L}_{X^n_s},\mathcal{L}_{X_s} \right)^2ds +C \lambda_n \,.
	  	\end{aligned}
\end{equation*}
Apply Gronwall's lemma, we have 
\begin{equation*}
\begin{aligned}
\mathbb{E}\left[ \sup_{t\leq T}\left|X^n_t - X_t\right|^2 \right]\leq C(1+\frac{M^2}{m^2})\exp\left \{ 8C(1+T)(1+\frac{M^2}{m^2}) \right \}\lambda_n\,.
\end{aligned}
\end{equation*}
Letting $n$ go to infinity, we complete this proof.

Apply the Lipschitz condition of $b$ and $\sigma$ and Cauchy-Schwarz inequality, we have 
	\begin{equation}\label{eq:th_5_3_1}
\begin{aligned}
	  \mathbb{E}\left[ \sup_{t\leq T}|X^n_t - X_t|^2 \right]&\leq 4\mathbb{E}\left \{ \sup_{t\leq T}\left[ \int_0^t \left|b\left( X^n_s,\mathcal{L}_{X^n_s} \right)-b(X_s,\mathcal{L}_{X_s})\right|dA^n_s \right]^2 \right \} \\
	  &\qquad  + 4\mathbb{E}\left \{ \sup_{t\leq T}\left[ \int_0^t \left|\sigma\left( X^n_s,\mathcal{L}_{X^n_s} \right)-\sigma(X_s,\mathcal{L}_{X_s})\right|dM^n_s \right]^2 \right \}\\
	  &\qquad +4\mathbb{E}\left[ \sup_{t\leq T}\left( \int_0^t |b(X_s,\mathcal{L}_{X_s})|d|A^n_s-A_s| \right)^2 \right] \\
	  &\qquad +4\mathbb{E}\left[ \sup_{t\leq T}\left( \int_0^t |\sigma(X_s,\mathcal{L}_{X_s})|d|M^n_s-M_s| \right)^2 \right] +4\sup_{t\leq T}|K^n_t - K_t|^2\\
	  &\leq C\int_0^T\mathbb{E}\left[ \sup_{s\leq t}|X^n_s-X_s|^2 \right]+\mathcal{W}_2\left( \mathcal{L}_{X^n_s},\mathcal{L}_{X_s} \right)^2 \left( dA^n_s + d\left\langle M^n \right\rangle_s \right)+e_n\\
	  &\qquad +4\sup_{t\leq T}|K^n_t - K_t|^2\,,
\end{aligned}
\end{equation}
where
$$
e_n = 4\mathbb{E}\left[ \sup_{t\leq T}\left( \int_0^t |b(X_s,\mathcal{L}_{X_s})|d|A^n_s-A_s| \right)^2 \right]+4\mathbb{E}\left[ \sup_{t\leq T}\left( \int_0^t |\sigma(X_s,\mathcal{L}_{X_s})|d|M^n_s-M_s| \right)^2 \right]\,.
$$
Moreover, 
\begin{equation}\label{eq:th_5_3_2}
\begin{aligned}
	  	\sup_{t\leq T}\left|K^{n}_t - K_t\right|^2&\leq \frac{M^2}{m^2}\mathbb{E}\left[ \sup_{r\in [0,t]}\left|U^{n}_r - U_r\right|^2 \right] \\
	  	&\leq \frac{M^2}{m^2}C\int_0^t\mathbb{E}\left[ |X^n_s-X_s|^2 \right] + \mathcal{W}_2\left( \mathcal{L}_{X^n_s},\mathcal{L}_{X_s} \right)^2ds +C e_n 
	  	\end{aligned}
\end{equation}
 Combining \eqref{eq:th_5_3_1} and \eqref{eq:th_5_3_2}, we have 
\begin{equation*}
\begin{aligned}
  \mathbb{E}\left[ \sup_{t\leq T}|X^n_t - X_t|^2 \right] \leq C \int_0^T\mathbb{E}\left[ \sup_{t\leq T}|X^n_t - X_t|^2 \right]\left( dA^n_s + d\left\langle M^n \right\rangle_s \right)+Ce_n\,.
\end{aligned}
\end{equation*}
Since $A^n_s+ \left\langle M^n \right\rangle_s$ is an increasing process, then according to the Stochastic Gronwall lemma, we obtain
$$
 \mathbb{E}\left[ \sup_{t\leq T}|X^n_t - X_t|^2 \right] \leq C e_n \mathbb{E}\left[ A^n_T+ \left\langle M^n \right\rangle_T \right]<\infty,
$$ 
using the assumptions of $(A_t,A_t^n,M_t,M_t^n)$, we have 
$$
\lim_{n\rightarrow \infty} e_n = 0\,.
$$
Therefore,
$$
\lim\limits_{n\rightarrow \infty}\mathbb{E}\left[ \sup_{t\leq T}|X^n_t - X_t|^2 \right] = 0\,.
$$

