 A family $\left\{X^{\varepsilon}\right\}_{\varepsilon>0}$ of $\mathcal{E}$-valued random variable is said to satisfy the large deviation principle on $\mathcal{E}$, with the good rate function $I$ and with the speed function $\lambda(\varepsilon)$ which is a sequence of positive numbers tending to $+\infty$ as $\varepsilon \rightarrow 0$, if the following conditions hold:
 \begin{enumerate}[(i)]
 	\item for each $M<\infty$, the level set $\{x \in \mathcal{E}: I(x) \leq M\}$ is a compact subset of $E$;
 	\item for each closed subset $F$ of $\mathcal{E}, \limsup _{\varepsilon \rightarrow 0} \frac{1}{\lambda(\varepsilon)} \log \mathbb{P}\left(X^{\varepsilon} \in F\right) \leq-\inf _{x \in F} I(x)$;
 	\item for each open subset $G$ of $\mathcal{E}, \liminf _{\varepsilon \rightarrow 0} \frac{1}{\lambda(\varepsilon)} \log \mathbb{P}\left(X^{\varepsilon} \in G\right) \geq-\inf _{x \in G} I(x)$.
 \end{enumerate}

\label{thm:LDP}
Let Assumptions \ref{ass:A_1} and \ref{ass:A_2} hold and $X^{\varepsilon}$ be the unique strong solution to \eqref{eq:4.1}. Then the family of $\left\{X^{\varepsilon}\right\}_{\varepsilon>0}$ satisfies a LDP on the space $\mathcal{X}$ with rate function
$$
I(\phi):=\inf _{\left\{h \in L^2\left([0, T], \mathbb{R}\right): \phi=Y^h\right\}} \frac{1}{2} \int_0^T|h(t)|^2 \mathrm{~d} t, \quad \phi \in \mathcal{X}
$$
with the convention $\inf \{\emptyset\}=+\infty$, here $Y^h \in \mathcal{X}$ solves equation \eqref{eq:ske_eq}.

For simplicity, we denote $Y^{h_n} : = \mathcal{G}^0\left( \int_0^{\cdot}h^n(s)ds \right)$, $Y^h = \mathcal{G}^0\left( \int_0^{\cdot}h(s)ds \right)$.
	\begin{equation}\label{eq:4_pro_1_1}
\begin{aligned}
	  Y^{h_n} - Y^h &= \int_0^t b\left( Y^{h^n}_s,\delta_{\psi_s} \right) - b\left( Y^h_s,\delta_{\psi_s} \right)ds + \int_0^t\sigma\left( Y^{h^n}_s,\delta_{\psi_s} \right) h^n(s) - \sigma\left( Y^h_s,\delta_{\psi_s} \right)h(s)ds \\
	  &\qquad+ K^{h^n}_t - K^h_t\\
	  & = \int_0^t b\left( Y^{h^n}_s,\delta_{\psi_s} \right) - b\left( Y^h_s,\delta_{\psi_s} \right)ds + \int_0^t\left[ \sigma\left( Y^{h^n}_s,\delta_{\psi_s} \right) - \sigma\left( Y^h_s,\delta_{\psi_s} \right) \right]h^n(s)ds\\
	  &\qquad + \int_0^t\sigma\left( Y^h_s,\delta_{\psi_s} \right)\left[ h^n(s)-h(s) \right]ds + K^{h^n}_t - K^h_t\\
	  &:= I^n_1(t) + I^n_2(t) + I^n_3(t) + I^n_4(t).
\end{aligned}
\end{equation}
Let $\kappa^n(t):= \sup_{r\in [0,t]}\left|Y^{h^n}(r) - Y^h(r)\right|$. By the Lipschitz condition of $b$, we have 
\begin{equation}\label{eq:4_pro_1_2}
\begin{aligned}
	  \left|I^n_1(t)\right| \leq \int_0^t \left|b\left( Y^{h^n}_s ,\delta_{\psi_s} \right)-b\left( Y^h_s,\delta_{\psi_s} \right)\right|ds \leq K\int_0^t \kappa^n(s)ds.
\end{aligned}
\end{equation}
By the Lipschitz condition of $\sigma$, we have 
\begin{equation}\label{eq:4_pro_1_3}
\begin{aligned}
	  \left|I^n_2(t)\right|\leq K\int_0^t|h^n(s)|\kappa_n(s)ds\,.
\end{aligned}
\end{equation}
By the linear growth of $\sigma$, we have 
\begin{equation*}
\begin{aligned}
	  \sup_{t\in [0,T]}\left|\sigma(x,\mu)\right|^2\leq C(1+K^2)
\end{aligned}
\end{equation*}
Since $h^n(t) \rightarrow h(t)$ weakly in $L^2\left( [0,T],\mathbb{R} \right)$ as $n\rightarrow \infty$, we have 
\begin{equation*}
\begin{aligned}
	  \int_0^T\left|h^n(s)\right|^2ds \leq C(h) \quad \int_0^T\left|h(s)\right|^2ds \leq C(h).
\end{aligned}
\end{equation*}
Then, by the Cauchy-Schwarz inequality, we have 
\begin{equation}\label{eq:4_pro_1_4}
\begin{aligned}
	  \sup_{t\in [0,T]} \left|I^n_3(t)\right|&\leq \int_0^T \left|\sigma\left( Y^h_s,\delta_{\psi_s} \right)\left[ h^n(s)-h(s) \right]\right|ds\\
	  &\leq \left( \int_0^T\left|\sigma\left( Y^h_s,\psi_s \right)\right|^2ds \right)^{\frac{1}{2}}\left( \int_0^T\left|h^n(s)-h(s)\right|^2 \right)^{\frac{1}{2}}\\
	  &\leq \left(  T \sup_{t\in [0,T]}\left|\sigma\left( Y^h_s,\psi_s \right) \right|^2 \right)^{\frac{1}{2}}\left( 2 \int_0^T\left( |h^n(s)|^2+|h(s)|^2 \right)ds \right)^{\frac{1}{2}}\\
	  &\leq (CT(1+K^2)C(h))^{\frac{1}{2}}<\infty .
\end{aligned}
\end{equation}
Similarly, we have, for any $0\leq t_1\leq t_2\leq T$,
$$
\left|I^n_3(t_2) - I^n_3(t_1)\right|\leq \left[ C(t_2-t_1)(1+K^2)C(h) \right]^{\frac{1}{2}},
$$
which means that the sequence $\left \{ I^n_3:n\geq 1 \right \}$ is equi-continuous. By the Arzela-Ascoli theorem, we deduce that $\left \{ I^n_3:n\geq 1 \right \}$ is relatively compact in $\mathcal{C}\left( [0,T],\mathbb{R} \right)$.

We can deduce that for any $t \in [0,T]$,
\begin{equation}\label{eq:4_pro_1_5}
\begin{aligned}
	  I^n_3(t) = \int_0^t\left( h^n(s)-h(s) \right)\sigma\left( Y^h_s,\delta_{\psi_s} \right)ds\rightarrow 0 \quad \text{as } n \rightarrow \infty\,.
\end{aligned}
\end{equation}
Together with the relative compactness of $\left \{ I^n_3:n\geq 1 \right \}$ in $\mathcal{C}\left( [0,T],\mathbb{R} \right)$, we can get 
\begin{equation*}
\begin{aligned}
	  \lim\limits_{n\rightarrow \infty}\sup_{t\in [0,T]}|I^n_3(t)| = 0\,.
\end{aligned}
\end{equation*}

By Lemma \ref{lem:2.2} , we have 
\begin{equation}\label{eq:4_pro_1_6}
\begin{aligned}
	  K^{h^n}_t - K^h_t\leq \frac{M}{m}\sup_{r\in [0,t]}\left|U^{h^n}_r - U^h_r\right| = \frac{M}{m}\sup_{r \in [0,t]}\left[ |I^n_1|(r) + |I^n_2|(r) \right]\,.
	  \end{aligned}
\end{equation}
Combing \eqref{eq:4_pro_1_1}, \eqref{eq:4_pro_1_2}, \eqref{eq:4_pro_1_3}, \eqref{eq:4_pro_1_4} and \eqref{eq:4_pro_1_6} together, we have 
\begin{equation*}
\begin{aligned}
	  \kappa^n(t)&\leq C\left \{ \int_0^t\kappa^n(s)ds + \int_0^t\kappa^n(s)\left|h^n(s)\right|ds \right \}+ 2\sup_{t\in [0,T]}\left|I^n_3(t)\right|\,.
\end{aligned}
\end{equation*}
Then, by \eqref{eq:4_pro_1_5} and Gronwall's lemma, we have 
\begin{equation}
\begin{aligned}
	  \kappa^n(T)&\leq 2\sup_{t\in [0,T]}|I^n_3(t)|\exp\left \{ C\int_0^T|h^n(s)|ds \right \}\\
	  & \leq C\sup_{t\in [0,T]}|I^n_3(t)| \rightarrow 0 \quad \text{as }n\rightarrow\infty.
\end{aligned}
\end{equation}
The proof is complete.

\begin{equation}\label{eq:4_lemma_1_1}
\begin{aligned}
	  \mathbb{E}\left[ \sup_{t\in [0,T]}\left|X^\varepsilon_t - \psi_t\right|^2 \right]&\leq 3\left\{\mathbb{E}\left[  \sup_{t\in [0,T]}\int_0^tb\left( X^\varepsilon_s,\mathcal{L}_{X^\varepsilon_s} \right)-b\left( \psi_s,\delta_{\psi_s} \right)ds \right]^2
	  \right.\\
	  &\qquad \left.+\varepsilon\mathbb{E}\left[ \sup_{t\in [0,T]}\int_0^t\sigma\left( X^\varepsilon_s,\mathcal{L}_{X^\varepsilon_s} \right)dB_s \right]^2 + \sup_{t\in [0,T]}\left|K^\varepsilon_t - K^\psi_t\right|^2\right\}\\
	  &=: I_1 + I_2 + I_3.
\end{aligned}
\end{equation}

By the Lipschitz condition of $b$ and $\sigma$, we have 
\begin{equation}\label{eq:4_lemma_1_2}
\begin{aligned}
	  I_1\leq TK\int_0^T\left \{ \mathbb{E}\left[ \left|X^\varepsilon_s - \psi_s\right|^2 \right]+ \mathcal{W}_2\left( \mathcal{L}_{X^\varepsilon_s},\delta_{\psi_s} \right)^2 \right \}ds\,,
\end{aligned}
\end{equation}
\begin{equation}\label{eq:4_lemma_1_3}
\begin{aligned}
	  {I_2\leq \mathbb{E}\int_0^T \sigma\left( X^\varepsilon_s,\mathcal{L}_{X^\varepsilon_s} \right)^2ds\leq \mathbb{E}\int_0^TC(1+{X^\varepsilon_s})^2ds}\,,
\end{aligned}
\end{equation}
\begin{equation}\label{eq:4_lemma_1_4}
\begin{aligned}
	  I_3 = \sup_{t\in [0,T]}\left|K^\varepsilon_t - K^\psi_t\right|^2&\leq\frac{M^2}{m^2}\mathbb{E}\left[ \sup_{r\in [0,t]}\left|U^\varepsilon_r- U^\psi_r\right|^2 \right]\leq 3 \frac{M^2}{m^2}(I_1+I_2)\,.
\end{aligned}
\end{equation}
Putting \eqref{eq:4_lemma_1_2}, \eqref{eq:4_lemma_1_3} and \eqref{eq:4_lemma_1_4} to \eqref{eq:4_lemma_1_1} and applying the Gronwall's lemma, we have 
\begin{equation}\label{eq:4_lemma_1_5}
\begin{aligned}
	  \mathbb{E}\left[ \sup_{t\in [0,T]}\left|X^\varepsilon_t - \psi_t\right|^2 \right]\leq e^{C}\left \{ T \int_0^T\mathcal{W}_2\left( \mathcal{L}_{X^\varepsilon_s},\delta_{\psi_s} \right)^2ds + \varepsilon \right \}\,.
\end{aligned}
\end{equation}

By the definition of $\mathcal{W}_2\left( \mathcal{L}_{X^\varepsilon_t},\delta_{\psi_t} \right)$, we have following estimation
\begin{equation*}
\begin{aligned}
\mathcal{W}_2\left( \mathcal{L}_{X^\varepsilon_t},\delta_{\psi_t} \right)^2\leq \mathbb{E}\left[ \sup_{t\in [0,T]}\left|X^\varepsilon_t - \psi_t\right|^2 \right]\leq e^{C}\left \{ T \int_0^T\mathcal{W}_2\left( \mathcal{L}_{X^\varepsilon_s},\delta_{\psi_s} \right)^2ds + \varepsilon \right \}\,.
\end{aligned}
\end{equation*}
Thanking to  Gronwall's lemma, we have 
$$
	\lim_{\varepsilon \rightarrow 0}\sup_{t \in [0,T]}\mathcal{W}_2\left( \mathcal{L}_{X^\varepsilon_t},\delta_{\psi_t} \right)^2 = 0\,.
	$$

By Chebyshev's inequality, we only need to show that 
$$
\lim _{\varepsilon \rightarrow 0} \mathbb{E}\left[\sup _{t \in[0, T]}|Z_t^{\varepsilon}-Y_t^{h^{\varepsilon}}|^2\right]=0\,.
$$
Then, it follows that 
\begin{equation}\label{eq:4_pro_2_1}
\begin{aligned}
	  \mathbb{E}\left[ \sup_{t\in [0,T]}\left|Z^\varepsilon_t - Y^{h^\varepsilon_t}\right|^2 \right]&\leq T\mathbb{E}\left \{ \sup_{t\in [0,T]}\int_0^T\left|b\left( Z^\varepsilon_s,\mathcal{L}_{X^\varepsilon_s} \right)-b\left( Y^{h^\varepsilon}_s,\delta_{\psi_s} \right)\right|^2ds \right \}\\
	  &\qquad + \mathbb{E}\left \{ \sup_{t\in [0,T]}\left[ \int_0^T 
	  h^\varepsilon(s)
	  \left[ \sigma \left( Z^\varepsilon_s,\mathcal{L}_{X^\varepsilon_s} \right) - \sigma\left( Y^{h^\varepsilon}_s,\delta_{\psi_s} \right) \right]ds \right]^2 \right \}\\
	  &\qquad + \varepsilon C_p\int_0^T\sigma\left( Z^\varepsilon_s,\mathcal{L}_{X^\varepsilon_s} \right)^2ds + \sup_{t\in [0,T]}\left|K^{Z^\varepsilon}_t - K^{h^\varepsilon}_t\right|^2\\
	  &\leq KT\sup_{t\in [0,T]}\mathbb{E}\int_0^T\left[ \left|Z^\varepsilon_s - Y^{h^\varepsilon}_s\right|^2 + \mathcal{W}_2\left( \mathcal{L}_{X^\varepsilon_s},\delta_{\psi_s} \right)^2 \right]ds \\
	  &\qquad+N\sup_{t\in [0,T]}\mathbb{E}\int_0^T\left[ \left|Z^\varepsilon_s - Y^{h^\varepsilon}_s\right|^2 + \mathcal{W}_2\left( \mathcal{L}_{X^\varepsilon_s ,\delta_{\psi_s}} \right)^2 \right]ds \\
	  &\qquad +\sup_{t\in [0,T]}\left|K^{Z^\varepsilon}_t - K^{h^\varepsilon}_t\right|^2\,.
	  \end{aligned}
\end{equation}
And 
\begin{equation}\label{eq:4_pro_2_2}
\begin{aligned}
	  \sup_{t\in [0,T]}\left|K^{Z^\varepsilon}_t - K^{h^\varepsilon}_t\right|^2 &\leq \frac{M^2}{m^2}\sup_{r\in [0,t]}\left|U^{Z^\varepsilon}_r - U^{h^{\varepsilon}}_r\right|^2 \\
	  &\leq \frac{M^2}{m^2}KT\int_0^T\mathbb{E}\left[ \sup_{t\in [0,T]}\left|Z^\varepsilon_s - Y^{h^\varepsilon}_s\right|^2 + \mathcal{W}_2\left( \mathcal{L}_{X^\varepsilon_s},\delta_{\psi_s} \right)^2 \right]ds \\
	  &\qquad +\frac{M^2}{m^2}N\int_0^T\mathbb{E}\left[ \sup_{t\in [0,T]}\left|Z^\varepsilon_s - Y^{h^\varepsilon}_s\right|^2 + \mathcal{W}_2\left( \mathcal{L}_{X^\varepsilon_s ,\delta_{\psi_s}} \right)^2 \right]ds\,.
\end{aligned}
\end{equation}
By \eqref{eq:4_pro_2_1} and \eqref{eq:4_pro_2_2} and apply Gronwall's lemma, we deduce that 
\begin{equation}
\begin{aligned}
	  \mathbb{E}\left[ \sup_{t\in [0,T]}\left|Z^\varepsilon_t - Y^{h^\varepsilon_t}\right|^2 \right]&\leq \left( CT+N \right)(1+\frac{M^2}{m^2})\int_0^t\mathbb{E}\sup_{t\in[0,s]}\left|Z^\varepsilon_s - Y^{h^\varepsilon}_s\right|^2ds \\
	  &\qquad+ \left( CT+N \right)(1+\frac{M^2}{m^2}) T\sup_{t\in [0,T]}\mathcal{W}\left( \mathcal{L}_{X^\varepsilon_t},\delta_{\psi_t} \right) + C(1+\frac{M^2}{m^2})\varepsilon\,.
	  \end{aligned}
\end{equation}

Apply Gronwall's lemma, Lemma \ref{lem:4.4} and letting $\varepsilon \rightarrow \infty$, we get 
$$
\lim _{\varepsilon \rightarrow 0} \mathbb{E}\left[\sup _{t \in[0, T]}|Z_t^{\varepsilon}-Y_t^{h^{\varepsilon}}|^2\right]=0\,.
$$
The proof is complete.

\label{lem:6.3}
	Suppose Assumptions \ref{ass:A_1} and \ref{ass:A_2} hold, and $\sigma(x)^{-1}<\infty$. Let $X_0$, $Y_0$ be two $\mathcal{F}_0-$measurable random variables such that $\mathcal{L}_{\xi^{X_0}} = \mu_0$, $\mathcal{L}_{\xi^{Y_0}} = \nu_0$ and
\begin{equation*}
\begin{aligned}
	  \mathbb{E}\left[ \left|\xi^{X_0}-\xi^{Y_0}\right|^2 \right] = \mathcal{W}_2\left( \mu_0,\nu_0 \right)^2\,.
\end{aligned}
\end{equation*}
Then $\left( R_t \right)_{t\in [0,T]}$ is a uniformly intgrable martingale with 
\begin{equation*}
\begin{aligned}
	  \sup_{t\in [0,T]}\mathbb{E}\left[ R_t\log R_t \right]\leq \phi(0,T)\mathcal{W}_2\left( \mu_0,\nu_0 \right)^2\,.
\end{aligned}
\end{equation*}

By Assumption \ref{ass:A_1}, for any $n\geq 1$, $\left( R_{t\wedge\tau_n} \right)_{t\in [0,T]}$ is a uniformly integrable continuous martingale. Since $\tau_n \rightarrow T$ as $n\rightarrow \infty$, by the martingale convergence Theorem, we only need to prove 
\begin{equation}\label{eq:lem_6_3_1}
\begin{aligned}
	  \sup_{t\in[0,T), n\geq 1}\mathbb{E}\left[ R_{t\wedge \tau_n}\log R_{t\wedge \tau_n} \right]\leq \phi(0,T) \mathcal{W}_2\left( \mu_0,\nu_0 \right)^2\,.
\end{aligned}
\end{equation}

We fix $t \in [0,T)$ and $n\geq 1$. By Girsanov's Theorem, 
$$
\tilde{B}_s:=B_s - \frac{1}{\xi_s}\sigma(X_s)^{-1}(Y_s-X_s), s \in [0,t \wedge \tau_n ] \,,
$$
is a Brownian motion under the weighted probability $\mathbb{Q}_{t,n}: = R_{t\wedge \tau_n} \mathbb{P}$.

Under  $\mathbb{Q}_{t,n}$, reformulating \eqref{eq:6_2_1} and \eqref{eq:6_2_2}
\begin{equation*}
\left\{\begin{array}{l}
X_{t\wedge \tau_n}=\xi^{X_0}+\int_0^{t\wedge \tau_n} b\left(X_s, \mathcal{L}_{X_s}\right)-\frac{X_s-Y_s}{\xi_s} d s+\int_0^{t\wedge \tau_n}  \sigma\left(X_s\right) d \tilde{B}_s+\tilde{K}^X_{t\wedge \tau_n} \\
\mathbb{E}^{\mathbb{Q}_{t,n}}\left[h\left(X_t\right)\right] \geq 0, \quad \int_0^t \mathbb{E}^{\mathbb{Q}_{t,n}}\left[h\left(X_s\right)\right] d\tilde{K}^X_s=0
\end{array}\right.\,.
\end{equation*}

\begin{equation*}
\left\{\begin{array}{l}
Y_{t\wedge \tau_n}=\xi^{Y_0}+\int_0^{t\wedge \tau_n} b\left(Y_s, \mathcal{L}_{Y_s}\right)d s+\int_0^{t\wedge \tau_n}  \sigma\left(Y_s\right) d \tilde{B}_s+\tilde{K}^Y_{t\wedge \tau_n} \\
\mathbb{E}\left[h\left(Y_{t\wedge \tau_n}\right)\right] \geq 0, \quad \int_0^{t\wedge \tau_n} \mathbb{E}^{\mathbb{Q}_{t,n}}\left[h\left(Y_s\right)\right] d\tilde{K}^Y_s=0
\end{array}\right.\,.
\end{equation*}
Apply It\^{o}'s Lemma, we have 
\begin{equation*}
\begin{aligned}
	  \left( X_{t\wedge\tau_n}-Y_{t\wedge \tau_n} \right)^2&\leq \int_0^{t\wedge\tau_n}C_1|X_s-Y_s|^2+C_2\mathcal{W}_2\left( \mu_s,\nu_s \right) - \frac{2|X_s-Y_s|^2}{\xi_s}ds\\
	  &+ \int_0^{t\wedge \tau_n}\left( X_s-Y_s \right)\left( \sigma(X_s)-\sigma(Y_s) \right)d\tilde{B}_s + \int_0^{t \wedge \tau_n}(X_s-Y_s)d\left( \tilde{K}^X_s - \tilde{K}^Y_s \right)
\end{aligned}
\end{equation*}
Using the same argument of proving Lemma \ref{lem:6.1}, we have 
$$
\int_0^{t \wedge \tau_n}(X_s-Y_s)d\left( \tilde{K}^X_s - \tilde{K}^Y_s \right)\leq 0\,.
$$
Then, applying Young's inequality, we have 
\begin{equation*}
\begin{aligned}
	  \frac{\left( X_{t \wedge \tau_n}-Y_{t\wedge \tau_n} \right)^2}{\xi_{t \wedge \tau_n}}&\leq \frac{C^2}{2}\int_0^{t \wedge \tau_n}\mathcal{W}_2\left( \mu_s,\nu_s \right)^2ds - \int_0^{t \wedge \tau_n}\left( \frac{3}{2} - C_1 \xi_s \right)\frac{|X_s - Y_s|^2}{\xi_s^2}ds \\
	  &+ \int_0^{t \wedge \tau_n}\frac{\left( X_s-Y_s \right)}{\xi_s}\left( \sigma(X_s)-\sigma(Y_s) \right)d\tilde{B}_s\,.
\end{aligned}
\end{equation*}
By the exponential convergence (Lemma \ref{lem:6.1}), we have 
$$
\mathcal{W}_2\left( \mu_s,\nu_s \right)\leq \mathcal{W}_2\left( \mu_0,\nu_0 \right)e^{(C_1+C_2)s}\,.
$$
Then, we have 
\begin{equation*}
\begin{aligned}
	  \mathbb{E}^{\mathbb{Q}_{t,n}}\int_0^{t\wedge \tau_n}\frac{|X_s - Y_s|^2}{\xi_s^2}ds &\leq \frac{2}{\xi_0}+ \mathbb{E}^{\mathbb{Q}_{t,n}}\int_0^{t\wedge \tau_n}C_2^2\mathcal{W}_2\left( \mu_s,\nu_s \right)^2ds \\
	  &\leq \frac{2}{\xi_0}+TC_2^2e^{2(C_1+C_2)T}\mathcal{W}_2\left( \mu_0,\nu_0 \right)^2\,.
\end{aligned}
\end{equation*}
Therefore, \eqref{eq:lem_6_3_1} holds since $t \in [0,T)$ and $n\geq 1$ are arbitrary.

By Lemma \ref{lem:6.3} and Girsanov's Theorem, $d\mathbb{Q} := R_T d\mathbb{P}$ is a probability measure such that 
	$$
	\tilde{B}_t : = B_t - \int_0^t\frac{\sigma(X_s)^{-1}(Y_s-X_s)}{\xi_s}ds \quad t\in [0,T]\,,
	$$
	is a Brownian motion. Then, \eqref{eq:6_2_2}
 can be written to 
 \begin{equation}\label{eq:Y_in_Q}
\left\{\begin{array}{l}
Y_{t}=\xi^{Y_0}+\int_0^{t} b\left(Y_s, \mathcal{L}_{Y_s}\right)d s+\int_0^{t}  \sigma\left(Y_s\right) d \tilde{B}_s+\tilde{K}^Y_t \\
\mathbb{E}^{\mathbb{Q}}\left[h\left(Y_t\right)\right] \geq 0, \quad \int_0^t \mathbb{E}^{\mathbb{Q}}\left[h\left(Y_s\right)\right] d\tilde{K}^Y_s=0
\end{array}\right.\,.
\end{equation}
Consider MR-MVSDE under $\mathbb{Q}$ measure
 \begin{equation}
\left\{\begin{array}{l}
\tilde{X}_{t}=\xi^{Y_0}+\int_0^{t} b\left(\tilde{X}_s, \mathcal{L}_{\tilde{X}_s}\right)d s+\int_0^{t}  \sigma\left(\tilde{X}_s\right) d \tilde{B}_s+\tilde{K}^{\tilde{X}}_t \\
\mathbb{E}^{\mathbb{Q}}\left[h\left(\tilde{X}_t\right)\right] \geq 0, \quad \int_0^t \mathbb{E}^{\mathbb{Q}}\left[h\left(\tilde{X}_s\right)\right] d\tilde{K}^Y_s=0
\end{array}\right.\,.
\end{equation}
By Theorem \ref{thm:1}, we have $\tilde{X}_t = Y_t$ for $t\in [0,T]$. So we deduce that 
$$
\left( P_T \log f \right)(\nu_0) \leq \log\left( P_T f \right)(\mu_0) + \phi(0,T)\mathcal{W}_2\left( \mu_0,\nu_0 \right)^2\,.
$$
In particular,
$$
P_T\log f(x)\leq \left( \log P_T f \right)(y) + \phi(0,T) |x-y|^2\,.
$$
Following \cite{arnaudon2014equivalent}, we can get for any $f\in \mathcal{B}_b^+(\mathbb{R})$
$$
\left|\nabla P_{s,t} f\right|^2\leq 2\phi(s,t)\left[ P_{s,t}f^2 - \left( P_{s,t}f \right)^2 \right]\,.
$$
Repeating the proof of \cite{wang2018distribution}[Theorem 4.1 (ii)], we can obtain for any different $\mu_0$ and $\nu_0\in \mathcal{P}_2(\mathbb{R})$ and any $f\in \mathcal{B}_b^+(\mathbb{R})$,
\begin{equation*}
\begin{aligned}
& \frac{\left|\left(P_{s, t} f\right)\left(\mu_0\right)-\left(P_{s, t} f\right)\left(\nu_0\right)\right|^2}{\mathcal{W}_2\left(\mu_0, \nu_0\right)^2} \\
& \quad \leq 2 \phi(s, t) \sup _{\nu \in B\left(\mu_0, \mathcal{W}_2\left(\mu_0, \nu_0\right)\right)}\left\{\left(P_{s, t} f^2\right)(\nu)-\left(P_{s, t} f\right)^2(\nu)\right\} \,,
\end{aligned}
\end{equation*}
and 
\begin{equation*}
\begin{aligned}
\left\|P_{s, t}^* \mu_0-P_{s, t}^* v_0\right\|_{v a r} & :=2 \sup _{A \in \mathcal{B}_b\left(\mathbb{R}^d\right)}\left|\left(P_{s, t}^* \mu_0\right)(A)-\left(P_{s, t}^* v_0\right)(A)\right| \\
& \leq \sqrt{2 \phi(s, t)} \mathcal{W}_2\left(\mu_0, v_0\right)\,.
\end{aligned}
\end{equation*}
Then, we complete this proof.

\label{thm:well_posedness_sDP1}
	Under Assumptions \ref{ass:A_1} and \ref{ass:A_2}, the MR-MVSDE \eqref{eq:s_DP_1} has a unique deterministic flat solution $(X,K)$. Moreover, 
\begin{equation}
\forall t \geq 0, \quad K_t=\sup _{s \leq t} \inf \left\{x \geq 0: \mathbb{E}\left[h\left(x+U_s\right)\right] \geq 0\right\}=\sup _{s \leq t} G_0\left(\mathcal{L}_{U_s}\right),
\end{equation}
where $\left( U_t \right)_{0\leq t\leq T}$ is the process defined by :
\begin{equation}\label{eq:U}
\begin{aligned}
	  U_t = \xi + \int_0^t b(X_s,\mathcal{L}_{X_s})dA_s + \int_0^t \sigma(X_s,\mathcal{L}_{X_s})dM_s.
\end{aligned}
\end{equation}
With these notations, denoting by $\mathcal{L}_{U_s}$ the family of marginal laws of $\left( U_t \right)_{0\leq t\leq T}$ we have 
$$
K_t = \sup_{s\leq t}G_0(\mathcal{L}_{U_s}).
$$

Let us consider the set $\mathcal{C}^2 = \left \{ X \text{ is } \mathcal{F}-\text{adapted continuous process}, \mathbb{E}\left( \sup_{0\leq t\leq T}|X_t|^2< \infty \right) \right \} $. And let $\widetilde{X}\in \mathcal{C}^2$ be a given process. We set 
\begin{equation}
\tilde{U}_t=\xi+\int_0^t b\left(\tilde{X}_s, \mathcal{L}_{\tilde{X}_s}\right) d A_s+\int_0^t \sigma\left(\tilde{X}_s, \mathcal{L}_{\tilde{X}_s}\right) d M_s, \quad \operatorname{Law}\left(\tilde{U}_s\right)=: \mathcal{L}_{\tilde {U}_s}\,,
\end{equation}
and define the function $K$ by setting
$$
{K_t=\sup _{s \leq t} \inf \left\{x \geq 0: \mathbb{E}\left[h\left(x+\tilde{U}_s\right)\right] \geq 0\right\}=G_0\left(\mathcal{L}_{\tilde {U}_s}\right) .}
$$
The function $K$ being given, let us define the process $X$ by the formula
\begin{equation}
\begin{aligned}
	  X_t=\xi+\int_0^t b\left(\tilde{X}_s,\mathcal{L}_{\tilde{X}_s}\right) d A_s+\int_0^t \sigma\left(\tilde{X}_s,\mathcal{L}_{\tilde{X}_s}\right) d M_s+K_t .
\end{aligned}
\end{equation}

Based on the definition of $K$, we have $\mathbb{E}\left[ h(X_t) \right]\geq 0$, $K_t = G_0\left( \mathcal{L}_{\tilde{U}_t} \right), dK_t-a.e.$ and $G_0(\mathcal{L}_{\tilde{U}_t})>0, dK_t-a.e.$ Then we obtain 
$$
\begin{aligned}
\int_0^t \mathbb{E}\left[h\left(X_s\right)\right] d K_s & =\int_0^t \mathbb{E}\left[h\left(\tilde{U}_s+K_s\right)\right] d K_s \\
& =\int_0^t \mathbb{E}\left[h\left(\tilde{U}_s+G_0\left(\mathcal{L}_{\tilde{U}_s}\right)\right)\right] d K_s \\
& =\int_0^t \mathbb{E}\left[h\left(\tilde{U}_s+G_0\left(\mathcal{L}_{\tilde{U}_s}\right)\right)\right] \mathbbm{1}_{\left \{ G_0\left(\mathcal{L}_{\tilde{U}_s}\right)>0 \right \}} d K_s .
\end{aligned}
$$
Moreover, since $h$ is continuous, we have $\mathbb{E}\left[h\left(\tilde{U}_s+G_0\left(\mathcal{L}_{\tilde{U}_s}\right)\right)\right]=0$ as soon as $G_0\left(\mathcal{L}_{\tilde{U}_s}\right)>0$, so that
$$
\int_0^t \mathbb{E}\left[h\left(X_s\right)\right] d K_s=0\,.
$$


 Let $\tilde{X}, \tilde{X}^\prime \in \mathcal{C}^2$ and define $\tilde{U}$, $K$ and $\tilde{U}^\prime$, $K^\prime$ as above, using the some Brownian motion. We have from the Lipschitz assumption of $b$ and $\sigma$, B-D-G inequality 
 \begin{equation}\label{eq:A_Th_1.1}
\begin{aligned}
	  &\mathbb{E}\left[ \sup_{t\leq T}|\tilde{X}_t - \tilde{X}_t^\prime|^2 \right]\\
	  &\leq  3\mathbb{E} \left[\sup_{t\leq T}\left\{\left|\int_0^t\left( b\left( \tilde{X}_s,\mathcal{L}_{\tilde{X}_s} \right)- b\left( \tilde{X}^\prime_s,\mathcal{L}_{\tilde{X}^\prime_s} \right) 
	   \right)dA_s\right|^2 + \left|\int_0^t \left( \sigma\left( \tilde{X}_s,\mathcal{L}_{\tilde{X}_s} \right)-\sigma\left( \tilde{X}^\prime_s,\mathcal{L}_{\tilde{X}^\prime_s} \right) \right)dM_s\right|^2\right.\right.\\
	  &\left.\left.\qquad +\left|K_t - K^\prime_t\right|^2 \right\}\right]\\
	  &\leq3 \mathbb{E}\left[\left.T\cdot \sup _{t \leq T} \int_0^t\left(b\left(\tilde{X}_s, \mathcal{L}_{\tilde{X}_s}\right)-b\left(\tilde{X}_s^{\prime}, \mathcal{L}_{\tilde{X}_s^{\prime}}\right)\right) d A_s\right|^2\right]\\
     &\qquad+3 \mathbb{E}\left[\sup _{t \leq T}\left|\int_0^t\left(\sigma\left(\tilde{X}_s, \mathcal{L}_{\tilde{X}_s}\right)-\sigma\left(\tilde{X}^{\prime}_s, \mathcal{L}_{\tilde{X}^{\prime}_s}\right)\right) d M_s\right|^2\right]+ 3 \sup_{t\leq T}\left|K_t - K^\prime_t\right|^2 \\
	  & \leq C\int_0^t\mathbb{E}\left[ \sup_{t\leq T}|\tilde X_t-\tilde X^\prime_t|^2 \right]d(A_s+\left\langle M \right\rangle_s) + 3 \sup_{t\leq T}\left|K_t - K^\prime_t\right|^2   \,.



\end{aligned}
\end{equation}
From the representation of $K$ and Lemma \ref{lem:2.2}, we have 
\begin{equation}\label{eq:A_K_t}
\begin{aligned}
	  \sup_{t\leq T}|K_t-K^\prime_t|^2 &= \sup_{t\leq T}\left|\sup_{s\leq t}G_0(\mathcal{L}_{\tilde X_t})-\sup_{s\leq t}G_0(\mathcal{L}_{\tilde X_t^\prime})\right|\leq \sup_{t\leq T}\left|G_0(\mathcal{L}_{\tilde X_t})-G_0(\mathcal{L}_{\tilde X_t^\prime})\right|\\
	  &\leq \frac{M}{m} \mathbb{E}\left[\sup _{t \leq T}\left|\tilde{U}_t-\tilde{U}^{\prime}_t\right|^2\right] \leq  C\mathbb{E}\left[\sup _{t \leq T}\left|\tilde{X}_t-\tilde{X}_t^{\prime}\right|^2\right] \,.
\end{aligned}
\end{equation}
Plugging \eqref{eq:A_K_t} into \eqref{eq:A_Th_1.1}, and use the stochastic Gronwall lemma, we have 
$$
\mathbb{E}\left[ \sup_{t\leq T}|\tilde X_t - \tilde X_t^\prime|^2 \right]\leq  C(1+T) T \mathbb{E}\left[\sup _{t \leq T}\left|\tilde{X}_t-\tilde{X}_t^{\prime}\right|^2\right].
$$

Hence, there exists a positive $\tilde{T}$, depending on $b, \sigma$ and $h$ only, such that for all $T<\tilde{T}$, the map $\Phi$ is a contraction. We first deduce the existence and uniqueness of the solution on $[0, \tilde{T}]$ and then on $\mathbb{R}^{+}$ by iterating the construction.
